Here's how to implement a basic undo/redo system using the Command design pattern in Python:

```python
from abc import ABC, abstractmethod

class Command(ABC):
    """Abstract base command."""
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass

class TextEditor:
    def __init__(self):
        self.text = ""

    def insert(self, position, content):
        self.text = self.text[:position] + content + self.text[position:]

    def delete(self, position, length):
        self.text = self.text[:position] + self.text[position + length:]

class InsertCommand(Command):
    def __init__(self, editor, position, content):
        self.editor = editor
        self.position = position
        self.content = content

    def execute(self):
        self.editor.insert(self.position, self.content)

    def undo(self):
        self.editor.delete(self.position, len(self.content))

class DeleteCommand(Command):
    def __init__(self, editor, position, length, deleted_text):
        self.editor = editor
        self.position = position
        self.length = length
        self.deleted_text = deleted_text

    def execute(self):
        self.editor.delete(self.position, self.length)

    def undo(self):
        self.editor.insert(self.position, self.deleted_text)

class UndoRedoManager:
    def __init__(self):
        self.undo_stack = []
        self.redo_stack = []

    def execute(self, command):
        command.execute()
        self.undo_stack.append(command)
        self.redo_stack.clear()  # Clear redo on new action

    def undo(self):
        if not self.undo_stack:
            return
        command = self.undo_stack.pop()
        command.undo()
        self.redo_stack.append(command)

    def redo(self):
        if not self.redo_stack:
            return
        command = self.redo_stack.pop()
        command.execute()
        self.undo_stack.append(command)

# Example usage:
editor = TextEditor()
manager = UndoRedoManager()

cmd1 = InsertCommand(editor, 0, "Hello")
manager.execute(cmd1)  # text = "Hello"

cmd2 = InsertCommand(editor, 5, " World")
manager.execute(cmd2)  # text = "Hello World"

manager.undo()  # text = "Hello"
manager.undo()  # text = ""
manager.redo()  # text = "Hello"
```

The Command pattern encapsulates each action as an object with execute() and undo() methods. The UndoRedoManager maintains stacks of executed commands for undo/redo functionality.
